//! 🔄️ One original host view funds each surface projection and every displaced owner.
use super::*;
use std::mem::ManuallyDrop;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneSourceTake,RetainedCloneClose,RetainedCloneCursor,RetainedFieldCursor,retained_clone_grant_admits}};
use semio_framework::ViewModelWindowSelection;
type Displaced=(Option<SurfaceBinding>,Option<ViewModel>,[Option<String>;4]);
/// 🧷️ Cancellation retains its original input and partial projections until paid closure.
pub struct OriginalSurfaceRefresh{binding:OriginalSourceBinding,decoder:(u64,u64),registry:Option<usize>,body:usize,source:ManuallyDrop<Option<RetainedCloneSource<ViewModel>>>,cursor:RetainedFieldCursor<ViewModel>,new:ManuallyDrop<Option<ViewModel>>,strings:ManuallyDrop<[Option<String>;3]>,displaced:ManuallyDrop<Option<Displaced>>,retirement:RetainedCloneClose,selector:ViewModelWindowSelection,slot:usize,field:usize,utility:usize,offset:usize,phase:u8,focus_valid:bool,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"surface refresh changed its original source, registry or lifecycle")}
fn step(d:RetirementDemand)->RetainedCloneStep{RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes})}
fn demand<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn paid(cx:&mut StepContext<'_>,d:RetirementDemand)->Result<bool,OriginalTurnFailure>{if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),d){return Ok(false)}cx.consume_retained(step(d).progress())?;cx.consume_fuel(1);Ok(true)}
fn receive(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>)->Result<bool,OriginalTurnFailure>{
 if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),d){return Ok(false)}
 let result=cx.with_native_receiving::<_,semio_framework_value_native_owned::native_decoding::NativeConstructionStepFailure<ValueError>>(|native|native.receive_construction_step(d,|control,g|{control.charge(d.capacity_bytes)?;run(g)}));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());let accounted=cx.receiving_issued_grant().map(|g|cx.consume_receiving_retained(g,p)).transpose();cx.consume_fuel(p.copied_items as u64);match(result,accounted){(Ok(_),Ok(_))=>Ok(true),(Err(e),Ok(_))=>Err(e.into()),(Ok(_),Err(e))=>Err(e.into()),(Err(e),Err(receipt))=>{let mut e=OriginalTurnFailure::from(e);e.context_refusal=Some(receipt);Err(e)}}
}
impl OriginalSurfaceRefresh{
 pub fn admit(cx:&mut StepContext<'_>,slot:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..demand::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;semio_framework_job::admit_original_construction(cx,slot,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{binding,decoder,registry:None,body,source:ManuallyDrop::new(None),cursor:Default::default(),new:ManuallyDrop::new(None),strings:ManuallyDrop::new(Default::default()),displaced:ManuallyDrop::new(None),retirement:Default::default(),selector:Default::default(),slot:0,field:0,utility:0,offset:0,phase:0,focus_valid:true,closing:false}),step(d).progress()))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn ready(&self)->bool{self.phase==8&&!self.closing}
 pub fn advance(&mut self,registry:&mut SurfaceContexts,view:&mut Option<ViewModel>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.closing{return Err(invalid().into())}if self.ready(){return Ok(true)}if registry.cached_capture.is_some(){return Ok(false)}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original surface refresh cancelled").into())}let id=registry as*const _ as usize;if self.registry.is_some_and(|old|old!=id){return Err(invalid().into())}let body=self.body;
  match self.phase{
   0=>{if view.is_none(){if paid(cx,demand::<u8>())?{self.phase=8}return Ok(self.ready())}let birth=RetainedCloneSource::<ViewModel>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<ViewModel>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};let g=cx.retained_grant();if semio_framework_job::admit_original_construction(cx,&mut self.source,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let original=view.take().ok_or_else(invalid)?;match RetainedCloneSource::admit_owned(original,(),g){Ok(value)=>Ok(value),Err((e,original,()))=>{*view=Some(original);Err(e)}}})?{self.registry=Some(id);self.phase=1}},
   1=>{if self.slot>registry.slots.len(){if paid(cx,demand::<u8>())?{self.phase=7}}else if self.slot==registry.slots.len(){if paid(cx,demand::<u8>())?{self.phase=2}}else if let Some(binding)=registry.slots[self.slot].as_ref(){let source=self.source.as_ref().unwrap().borrow();let input=source.get();let target=match &binding.role{SurfaceRole::Section=>{if paid(cx,demand::<usize>())?{self.slot+=1}return Ok(false)},SurfaceRole::Window(id)=>Some(id.as_str()),SurfaceRole::Panel=>input.focused_window_id.as_deref()};if let Some(target)=target{let d=self.selector.demands(input,target,0,body)?;let g=cx.retained_grant();if !cx.should_yield()&&retained_clone_grant_admits(g,d){let p=self.selector.advance(input,target,0,body,g)?.progress();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)}if self.selector.complete(){let exists=self.selector.selected(input,target,0)?.is_some();if !exists&&matches!(binding.role,SurfaceRole::Window(_)){if paid(cx,demand::<Displaced>())?{*self.displaced=Some((registry.slots[self.slot].take(),None,Default::default()));self.phase=6}}else if paid(cx,demand::<u8>())?{self.focus_valid=exists;self.phase=2}}}else if paid(cx,demand::<u8>())?{self.phase=2}}else if paid(cx,demand::<usize>())?{self.slot+=1}},
   2=>{let source=self.source.as_ref().unwrap().borrow();if self.cursor.output_ready(){if paid(cx,demand::<Option<ViewModel>>())?{*self.new=self.cursor.take();self.cursor.begin_close();self.phase=3}}else{let d=self.cursor.advance_demands(source,body)?;receive(cx,d,|g|self.cursor.advance(source,body,g))?;}},
   3=>{if !self.cursor.terminal_is_empty(){let d=self.cursor.close_demands(body)?;semio_framework_job::close_original_retained_step(cx,d,|g|self.cursor.close_step(g))?;}else if paid(cx,demand::<u8>())?{self.phase=4}},
   4=>{if self.slot==registry.slots.len()||!matches!(registry.slots[self.slot].as_ref().ok_or_else(invalid)?.role,SurfaceRole::Window(_)){if paid(cx,demand::<u8>())?{self.phase=5}}else{let binding=registry.slots[self.slot].as_ref().unwrap();let target=binding.role.window_id().ok_or_else(invalid)?;let source=self.source.as_ref().unwrap().borrow();let input=source.get();let window=self.selector.selected(input,target,0)?.ok_or_else(invalid)?;if self.field==2{if let Some((key,_))=input.active_utility_by_window_id.entry_at_rank(self.utility){let n=if key.len()==target.len(){(key.len()-self.offset).min(64)}else{0};if !paid(cx,RetirementDemand{copy_bytes:2*n+3*size_of::<usize>(),depth:1,..Default::default()})?{return Ok(false)}if key.len()!=target.len()||key.as_bytes()[self.offset..self.offset+n]!=target.as_bytes()[self.offset..self.offset+n]{self.utility+=1;self.offset=0;return Ok(false)}self.offset+=n;if self.offset<key.len(){return Ok(false)}self.offset=0;self.field=3;}else if paid(cx,demand::<usize>())?{self.field=4}return Ok(false)}let text=match self.field{0=>Some(window.id.as_str()),1=>Some(window.window_kind_id.as_str()),3=>input.active_utility_by_window_id.entry_at_rank(self.utility).map(|(_,v)|v.as_str()),_=>None};let index=if self.field==3{2}else{self.field};if let Some(text)=text{if self.strings[index].is_none(){let d=RetirementDemand{capacity_bytes:text.len(),..demand::<Option<String>>()};receive(cx,d,|_|{self.strings[index]=Some(String::with_capacity(text.len()));Ok(step(d))})?;}else{let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}let d=RetirementDemand{copy_bytes:end-self.offset+2*size_of::<usize>(),depth:1,..Default::default()};if paid(cx,d)?{self.strings[index].as_mut().unwrap().push_str(&text[self.offset..end]);self.offset=end;if end==text.len(){self.offset=0;self.field+=1}}}}else if paid(cx,demand::<u8>())?{self.phase=5}}},
   5=>{if paid(cx,demand::<Displaced>())?{let mut next=self.new.take().ok_or_else(invalid)?;let mut old: [Option<String>;4]=Default::default();if self.slot<registry.slots.len(){old[0]=next.window_id.take();old[1]=next.active_window_kind_id.take();old[2]=next.active_utility_id.take();if !self.focus_valid{old[3]=next.focused_window_id.take()}next.window_id=self.strings[0].take();next.active_window_kind_id=self.strings[1].take();next.active_utility_id=self.strings[2].take();let previous=registry.slots[self.slot].as_mut().ok_or_else(invalid)?.view_state.replace(next);*self.displaced=Some((None,previous,old));}else{*self.displaced=Some((None,registry.view_state.replace(next),old));}self.phase=6}},
   6=>{if self.close_displaced(cx)?&&paid(cx,demand::<Self>())?{self.cursor=Default::default();self.selector=Default::default();self.field=0;self.utility=0;self.offset=0;self.focus_valid=true;self.slot+=1;self.phase=1}},
   7=>{let d=self.source.as_ref().unwrap().next_take_demand(body)?;let g=cx.retained_grant();if !cx.should_yield()&&retained_clone_grant_admits(g,d){match self.source.as_mut().unwrap().take_authority(g)?{RetainedCloneSourceTake::Pending(p)=>{cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)},RetainedCloneSourceTake::Ready(original,p)=>{*view=Some(original);self.source.take();self.phase=8;cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)}}}},
   _=>return Err(invalid().into())
  }Ok(self.ready())
 }
 fn close_displaced(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let body=self.body;if !self.retirement.is_empty(){let mut selected=self.retirement.select(body)?;let d=selected.demands();semio_framework_job::close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}if self.displaced.is_some(){let d=self.retirement.next_owner_demands::<Displaced>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.displaced,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.closing=true;let body=self.body;self.cursor.begin_close();if !self.cursor.terminal_is_empty(){let d=self.cursor.close_demands(body)?;semio_framework_job::close_original_retained_step(cx,d,|g|self.cursor.close_step(g))?;return Ok(false)}if !self.close_displaced(cx)?{return Ok(false)}macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.$field,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}}}close!(new,ViewModel);close!(source,RetainedCloneSource<ViewModel>);if self.strings.iter().any(Option::is_some){if paid(cx,demand::<Displaced>())?{let strings=std::mem::take(&mut*self.strings);let[a,b,c]=strings;*self.displaced=Some((None,None,[a,b,c,None]));}return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.new.is_none()&&self.strings.iter().all(Option::is_none)&&self.displaced.is_none()&&self.retirement.is_empty()&&self.cursor.terminal_is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalSurfaceRefresh{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original surface refresh requires paid physical closure")}}
impl SurfaceContexts{
 /// 🪦️ Cached projections retire one genuine binding and one original view at a time.
 pub fn close_original_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.cached_capture.is_some(){return Ok(false)}if self.closing_body.is_none(){let body=cx.retained_grant().maximum_copy_bytes;if paid(cx,demand::<Option<usize>>())?{self.closing_body=Some(body)}return Ok(false)}let body=self.closing_body.unwrap();if !self.retirement.is_empty(){let mut selected=self.retirement.select(body)?;let d=selected.demands();semio_framework_job::close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}if self.closing_slot<self.slots.len(){let slot=&mut self.slots[self.closing_slot];if slot.is_some(){let d=self.retirement.next_owner_demands::<SurfaceBinding>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(slot,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;}else if paid(cx,demand::<usize>())?{self.closing_slot+=1}return Ok(false)}if self.view_state.is_some(){let d=self.retirement.next_owner_demands::<ViewModel>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.view_state,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn original_terminal_is_empty(&self)->bool{self.slots.iter().all(Option::is_none)&&self.view_state.is_none()&&self.retirement.is_empty()&&self.cached_source.is_none()&&self.cached_capture.is_none()&&self.captured_slot.is_none()}
 /// 🧪️ Source-only fixture setup creates all authored surface roles before receipt observation.
 #[cfg(feature="original-surface-testing")]
 pub fn original_refresh_fixture(view:&ViewModel)->Self{let mut result=Self::default();for(index,(surface,role))in [("window",SurfaceRole::Window("energy-window".into())),("panel",SurfaceRole::Panel),("section",SurfaceRole::Section),("closed",SurfaceRole::Window("closed-window".into()))].into_iter().enumerate(){let mut old=view.clone();old.panel_json=Some("original section".into());result.slots[index]=Some(SurfaceBinding{surface:surface.into(),body_key:surface.into(),role,view_state:Some(old),version:0});}result}
 /// 🧪️ The original cached view exists before native read admission begins.
 #[cfg(feature="original-surface-testing")]
 pub fn original_read_fixture(view:&ViewModel)->Self{Self{view_state:Some(view.clone()),..Self::default()}}
 /// 🔬️ Checks role projections through borrowed originals without minting a cold view.
 #[cfg(feature="original-surface-testing")]
 pub fn assert_original_refresh_fixture(&self,view:&ViewModel){let window=self.slots[0].as_ref().unwrap().view_state.as_ref().unwrap();assert_eq!(window.window_id.as_deref(),Some("energy-window"));assert_eq!(window.active_window_kind_id.as_deref(),Some("energy-main"));assert_eq!(window.active_utility_id.as_deref(),Some("inspect"));let panel=self.slots[1].as_ref().unwrap().view_state.as_ref().unwrap();assert!(panel.window_id.is_none()&&panel.active_window_kind_id.is_none()&&panel.active_utility_id.is_none());assert_eq!(self.slots[2].as_ref().unwrap().view_state.as_ref().unwrap().panel_json.as_deref(),Some("original section"));assert!(self.slots[3].is_none());for actual in [window,panel,self.view_state.as_ref().unwrap()]{assert_eq!(actual.panel_json,view.panel_json);assert_eq!(actual.active_utility_by_window_id.original_root_identity(),view.active_utility_by_window_id.original_root_identity());assert_eq!(actual.tool_run_trace_cursor_by_window_id.original_root_identity(),view.tool_run_trace_cursor_by_window_id.original_root_identity());}}
}

#[path="read.rs"]mod read;
pub use read::OriginalSurfaceViewCapture;

#[cfg(feature="original-surface-testing")]
impl SurfaceContexts{#[doc(hidden)]pub fn original_surface_read_fixture(surface:&str,view:&ViewModel)->Self{let mut result=Self::default();let mut cached=view.clone();cached.window_id=Some("cache-window".into());result.view_state=Some(cached);result.slots[0]=Some(SurfaceBinding{surface:"cached".into(),body_key:"section".into(),role:SurfaceRole::Section,view_state:Some(result.view_state.as_ref().unwrap().clone()),version:0});result.slots[1]=Some(SurfaceBinding{surface:surface.into(),body_key:"section".into(),role:SurfaceRole::Section,view_state:Some(view.clone()),version:0});result}}
